from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient

counts = {"function": 0, "request": 0}

def dep_function_scoped():
    counts["function"] += 1
    return "value"

def dep_request_scoped():
    counts["request"] += 1
    return "value"

app = FastAPI()

@app.get("/function", dependencies=[Depends(dep_function_scoped, scope="function")])
def read_function(d1=Depends(dep_function_scoped, scope="function")):
    return {"count": counts["function"]}

@app.get("/request", dependencies=[Depends(dep_request_scoped, scope="request")])
def read_request(d1=Depends(dep_request_scoped, scope="request")):
    return {"count": counts["request"]}

client = TestClient(app)

def test_scopes():
    # Test function scope
    counts["function"] = 0
    resp_func = client.get("/function")
    print(f"Function scope count: {resp_func.json()['count']}")
    assert resp_func.json()["count"] == 2, f"Expected 2, got {resp_func.json()['count']}"

    # Test request scope
    counts["request"] = 0
    resp_req = client.get("/request")
    print(f"Request scope count: {resp_req.json()['count']}")
    assert resp_req.json()["count"] == 1, f"Expected 1, got {resp_req.json()['count']}"

if __name__ == "__main__":
    try:
        test_scopes()
        print("Tests passed!")
    except AssertionError as e:
        print(f"Test failed: {e}")
        exit(1)
