# Global call count for each dependency type
counts = {"function": 0, "request": 0}

def dep_function_scoped():
    counts["function"] += 1
    return "value"

def dep_request_scoped():
    counts["request"] += 1
    return "value"

app = FastAPI()

@app.get("/function", dependencies=[Depends(dep_function_scoped, scope="function")])
def read_function(d1=Depends(dep_function_scoped, scope="function")):
    return {"count": counts["function"]}

@app.get("/request", dependencies=[Depends(dep_request_scoped, scope="request")])
def read_request(d1=Depends(dep_request_scoped, scope="request")):
    return {"count": counts["request"]}

client = TestClient(app)

def test_scopes():
    # Test function scope
    counts["function"] = 0
    resp_func = client.get("/function")
    print(f"Function scope count: {resp_func.json()['count']}")
